"""Serial event-transport adaptation of the cached partial gather barrier.

The barrier caches one accepted response per endpoint.  Freshness, the first
response (which marks an endpoint seen) and the acceptance age decide whether
the cached coordinator may advance one round.
"""
import numpy as np


class PartialBarrier:

    def __init__(self, number_of_endpoints, min_arrival, max_lag, num_edges):
        self._number_of_endpoints = number_of_endpoints
        self._min_arrival = min_arrival if min_arrival is not None else number_of_endpoints
        self._max_lag = max_lag
        self._clock = 0
        self._arrival_set = set()
        self._storage = np.zeros((number_of_endpoints, num_edges))
        self._initial_response_set = set(range(number_of_endpoints))
        self._last_response = [None] * number_of_endpoints

    @property
    def clock(self):
        return self._clock

    @property
    def storage(self):
        return self._storage

    @property
    def arrivals(self):
        return self._arrival_set

    @property
    def seen(self):
        return set(range(self._number_of_endpoints)) - self._initial_response_set

    @property
    def fresh(self):
        return set(self._arrival_set)

    def ages(self):
        """Round age of every endpoint, ``None`` for endpoints never seen."""
        return [None if w not in self.seen else self._clock - self._last_response[w]
                for w in range(self._number_of_endpoints)]

    def blockers(self):
        """(missing, stale, fresh) worker ids reported by a blocked step."""
        seen = self.seen
        missing = [w for w in range(self._number_of_endpoints) if w not in seen]
        stale = [w for w in sorted(seen)
                 if self._clock - self._last_response[w] > self._max_lag]
        return missing, stale, sorted(self._arrival_set)

    def can_advance(self):
        if len(self.seen) != self._number_of_endpoints:
            return False
        if len(self._arrival_set) < self._min_arrival:
            return False
        for w in self.seen:
            if self._clock - self._last_response[w] > self._max_lag:
                return False
        return True

    def arrive(self, node_id, response):
        """Cache an accepted endpoint response; discards never refresh state."""
        if node_id < 0 or node_id >= self._number_of_endpoints:
            raise ValueError("unknown endpoint")
        payload = np.asarray(response, dtype=float).flatten()
        if payload.shape[0] != self._storage.shape[1]:
            raise ValueError("response shape mismatch")
        self._storage[node_id] = payload
        self._initial_response_set.discard(node_id)
        self._arrival_set.add(node_id)
        self._last_response[node_id] = self._clock
        return True

    def advance(self):
        """Advance one round when the barrier permits, else change nothing."""
        if not self.can_advance():
            return False
        self._clock += 1
        self._arrival_set = set()
        return True
